"""PCAN-View compatible .trc (v1.1, text format) writer.

Format checked byte-for-byte against files saved by PCAN-View v6.0.1.1047: CRLF line endings, an
OLE Automation Date (days since 1899-12-30, as used by `$STARTTIME`), and
fixed-width columns:

    ;$FILEVERSION=1.1
    ;$STARTTIME=46281.6137425694
    ;
    ;   Start time: 9/16/2026 14:43:47.358.0
    ;   Generated by CANopener
    ;
    ;   Message Number
    ;   |         Time Offset (ms)
    ;   |         |        Type
    ;   |         |        |        ID (hex)
    ;   |         |        |        |     Data Length
    ;   |         |        |        |     |   Data Bytes (hex) ...
    ;   |         |        |        |     |   |
    ;---+--   ----+----  --+--  ----+---  +  -+ -- -- -- -- -- -- --
         1)        12.5  Rx         0123  8  11 22 33 44 55 66 77 88
       132)      3456.7  Rx     18FF1234  8  0A 0B 0C 0D 0E 0F 10 11

Column widths: message number right-justified to 6 + ")"; time offset in ms
right-justified to 12 with one decimal, then two spaces; "Rx"; the ID (4 hex
digits for an 11-bit id, 8 for a 29-bit/extended id) right-justified to 13;
two spaces; DLC; two spaces; each data byte as two hex digits followed by a
trailing space (so the row itself ends with a trailing space when DLC > 0).
"""

from __future__ import annotations

import time
from datetime import datetime
from typing import Callable

import can
import canopen

_NOOP = lambda *a, **k: None  # noqa: E731

#: OLE Automation Date epoch (also PCAN-View's $STARTTIME epoch): 1899-12-30.
_OA_EPOCH = datetime(1899, 12, 30)


def _oadate(dt: datetime) -> float:
    return (dt - _OA_EPOCH).total_seconds() / 86400.0


def _write_trc_header(f, start_dt: datetime) -> None:
    """Write the `;`-prefixed PCAN-View v1.1 header block (shared by
    `TrcWriter` and `canbin.canbin_to_trc`, which supplies its own
    `start_dt` from the `.canbin` header instead of `datetime.now()`)."""
    oadate = _oadate(start_dt)
    f.write(";$FILEVERSION=1.1\n")
    f.write(f";$STARTTIME={oadate:.10f}\n")
    f.write(";\n")
    f.write(
        f";   Start time: {start_dt.month}/{start_dt.day}/{start_dt.year} "
        f"{start_dt:%H:%M:%S}.{start_dt.microsecond // 1000:03d}.0\n"
    )
    f.write(";   Generated by CANopener\n")
    f.write(";\n")
    f.write(";   Message Number\n")
    f.write(";   |         Time Offset (ms)\n")
    f.write(";   |         |        Type\n")
    f.write(";   |         |        |        ID (hex)\n")
    f.write(";   |         |        |        |     Data Length\n")
    f.write(";   |         |        |        |     |   Data Bytes (hex) ...\n")
    f.write(";   |         |        |        |     |   |\n")
    f.write(";---+--   ----+----  --+--  ----+---  +  -+ -- -- -- -- -- -- --\n")


class TrcWriter(can.Listener):
    """A can.Listener that appends every received frame to a PCAN-View v1.1
    .trc file."""

    def __init__(self, path):
        self.path = path
        self._file = None
        self._count = 0
        self._start_time = None  # monotonic-ish frame timestamp of message 1

    def __enter__(self) -> "TrcWriter":
        self._file = open(self.path, "w", newline="\r\n", encoding="ascii")
        self._write_header()
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def _write_header(self) -> None:
        _write_trc_header(self._file, datetime.now())

    def on_message_received(self, msg: can.Message) -> None:
        if msg.is_error_frame or self._file is None:
            return
        self.write_message(msg)

    def write_message(self, msg: can.Message) -> None:
        timestamp = msg.timestamp if msg.timestamp else time.time()
        if self._start_time is None:
            self._start_time = timestamp
        self._count += 1
        elapsed_ms = (timestamp - self._start_time) * 1000.0
        self._file.write(format_row(self._count, elapsed_ms, msg.arbitration_id,
                                     msg.is_extended_id, msg.dlc, msg.data))
        self._file.flush()

    def close(self) -> None:
        if self._file is not None:
            self._file.close()
            self._file = None


def format_row(n: int, elapsed_ms: float, can_id: int, extended: bool, dlc: int, data: bytes) -> str:
    """Format one PCAN-View v1.1 data row (without the trailing newline)."""
    id_str = f"{can_id:08X}" if extended else f"{can_id:04X}"
    data_str = "".join(f"{b:02X} " for b in data)
    return f"{n:>6}){elapsed_ms:>12.1f}  Rx{id_str:>13}  {dlc}  {data_str}\n"


def capture_trace(network: canopen.Network, seconds: float, out_path, log: Callable = _NOOP) -> int:
    """Capture bus traffic for `seconds` using the already-connected `network`
    and write it to `out_path`. Returns the number of frames written."""
    with TrcWriter(out_path) as writer:
        network.notifier.add_listener(writer)
        try:
            log(f"Capturing for {seconds}s -> {out_path}")
            time.sleep(seconds)
        finally:
            network.notifier.remove_listener(writer)
        count = writer._count
    log(f"Wrote {count} frame(s) to {out_path}")
    return count


# ---------------------------------------------------------------------------------------- v2.1 (FD, Tx, bus)

def _oadate_ts(ts: float) -> float:
    """OLE date of a Unix time in local time, as PCAN-View writes $STARTTIME."""
    return _oadate(datetime.fromtimestamp(ts))


class TrcWriter21:
    """PCAN-View v2.1 .trc writer: CAN FD, remote and error frames, Rx/Tx direction and bus number.

    Frames are CANopener frame tuples (ts, can_id, flags, dlc, data); `bus` is 1-based.
    Columns: N (number), O (offset ms), T (type), B (bus), I (id), d (Rx/Tx), R (reserved), L (length), D."""

    def __init__(self, path, start_ts: float | None = None):
        self.path = path
        self._file = open(path, "w", newline="\r\n", encoding="ascii")
        self.count = 0
        self._t0 = start_ts
        self._header_written = False

    def _header(self, t0: float) -> None:
        dt = datetime.fromtimestamp(t0)
        f = self._file
        f.write(";$FILEVERSION=2.1\n")
        f.write(f";$STARTTIME={_oadate_ts(t0):.10f}\n")
        f.write(";$COLUMNS=N,O,T,B,I,d,R,L,D\n")
        f.write(";\n")
        f.write(f";   Start time: {dt.month}/{dt.day}/{dt.year} {dt:%H:%M:%S}.{dt.microsecond // 1000:03d}.0\n")
        f.write(";   Generated by CANopener\n")
        f.write(";-------------------------------------------------------------------------------\n")
        f.write(";   Message   Time    Type    ID     Rx/Tx\n")
        f.write(";   Number    Offset  |  Bus  [hex]  |  Reserved\n")
        f.write(";   |         [ms]    |  |    |      |  |  Data Length Code\n")
        f.write(";   |         |       |  |    |      |  |  |    Data [hex] ...\n")
        f.write(";   |         |       |  |    |      |  |  |    |\n")
        f.write(";---+-- ------+------ +- +- --+----- +- +- +--- +- -- -- -- -- -- -- --\n")
        self._header_written = True

    def write(self, bus: int, frame) -> None:
        from .channel import F_BRS, F_ERR, F_ESI, F_EXT, F_FD, F_RTR, F_TX
        ts, can_id, flags, dlc, data = frame
        if self._t0 is None:
            self._t0 = ts
        if not self._header_written:
            self._header(self._t0)
        self.count += 1
        if flags & F_ERR:
            kind = "ER"
        elif flags & F_RTR:
            kind = "RR"
        elif flags & F_FD:
            kind = {0: "FD", F_BRS: "FB", F_ESI: "FE", F_BRS | F_ESI: "BI"}[flags & (F_BRS | F_ESI)]
        else:
            kind = "DT"
        id_str = f"{can_id:08X}" if flags & F_EXT else f"{can_id:04X}"
        from can.util import len2dlc
        length = dlc if flags & F_RTR else len2dlc(len(data))   # column L is the DLC code (FD 64 bytes = 15)
        payload = "" if flags & F_RTR else " ".join(f"{b:02X}" for b in data)
        self._file.write(f"{self.count:>7} {(ts - self._t0) * 1000.0:13.3f} {kind} {bus:>2} {id_str:>8} "
                         f"{'Tx' if flags & F_TX else 'Rx'} -  {length:<4} {payload}\n")

    def flush(self) -> None:
        self._file.flush()

    def close(self) -> None:
        if self._file is not None:
            if not self._header_written:
                self._header(self._t0 or time.time())
            self._file.close()
            self._file = None
